import subprocess, sys
BIN="/workspace/dataset/test15_executable"

def ref(b: bytes) -> bytes:
    out=bytearray(); cap=False
    for c in b:
        if c==0x5F: cap=True
        elif cap:
            out.append(c-0x20 if 0x61<=c<=0x7A else c); cap=False
        else: out.append(c)
    return bytes(out)

def camelize(w: bytes):
    """returns (camelize_bytes, exitcode, stderr)"""
    p=subprocess.run([BIN, w], capture_output=True)
    lines=p.stdout.split(b'\n')
    # structure: pluralize, camelize, isPlural, isSingular, demodulize, ''
    return lines, p.returncode, p.stderr

def cam2(w: bytes):
    """camelize via 2nd arg position: line indices 0..: pl(Q),cam(Q),pl(W),cam(W),und(W),isPl(Q),isSg(Q),demod(Q)"""
    p=subprocess.run([BIN, b"Q", w], capture_output=True)
    return p.stdout.split(b'\n'), p.returncode, p.stderr
EOF
