use strict; use warnings;
my $BIN="/workspace/dataset/test15_executable";

sub ref_cam {
  my ($s)=@_; my $out=''; my $cap=0;
  foreach my $c (unpack('C*',$s)) {
    if ($c==0x5F) { $cap=1; }
    elsif ($cap) { $out .= chr( ($c>=0x61 && $c<=0x7A) ? $c-0x20 : $c ); $cap=0; }
    else { $out .= chr($c); }
  }
  return $out;
}

sub run_args {
  my @args=@_;
  my ($rfh,$wfh);
  pipe($rfh,$wfh) or die;
  my $pid=fork(); die unless defined $pid;
  if ($pid==0) { close $rfh; open(STDOUT,'>&',$wfh) or die; open(STDERR,'>','/dev/null'); exec($BIN,@args); exit 127; }
  close $wfh; local $/; my $out=<$rfh>; close $rfh; waitpid($pid,0); my $st=$?;
  $out='' unless defined $out;
  return ($out, $st>>8, ($st & 127));
}

# camelize via single arg: line index 1
sub cam1 { my ($w)=@_; my ($out,$ec,$sig)=run_args($w); my @L=split(/\n/,$out,-1); return (defined $L[1]?$L[1]:undef, $out, $ec, $sig); }

my $fail=0; my $n=0;
sub t {
  my ($w,$label)=@_;
  my ($got,$raw,$ec,$sig)=cam1($w);
